fun <T> mutSetBy(size: Int, init: (Int) -> T, hash: (T) -> Long, eq: (T, T) -> Boolean): MutSet<T> {
    val s = SalvoSet<T>()
    for (i in 0 until size) s.put(init(i), hash, eq)
